package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Batch installer for already-authorized content records. It never derives mechanics from catalog/RAG text. */
public final class AuthorizedContentIngestionBatchEngine{
 private AuthorizedContentIngestionBatchEngine(){}
 public static JSONObject install(JSONArray records){JSONObject o=new JSONObject();JSONArray accepted=new JSONArray(),blocked=new JSONArray();int n=records==null?0:records.length();try{for(int i=0;i<n;i++){JSONObject x=records.optJSONObject(i);JSONObject r=installOne(x);if(r.optBoolean("installed",false))accepted.put(r);else blocked.put(r);}return o.put("requested",n).put("installed",accepted.length()).put("blocked",blocked.length()).put("accepted",accepted).put("blocked_records",blocked).put("mechanical_authority_granted_only_by_record_evidence",true).put("closure",ContentClosureQueueEngine.report());}catch(Exception e){try{return o.put("requested",n).put("installed",accepted.length()).put("blocked",blocked.length()+1).put("authority","blocked_batch_error");}catch(Exception ignored){return o;}}}
 public static JSONObject installOne(JSONObject x){JSONObject o=new JSONObject();try{if(x==null)return block("", "", "blocked_missing_record");String k=norm(x.optString("kind")),name=x.optString("name").trim();if("statblock_scope".equals(k)){JSONObject rr=AuthorizedBestiaryScopeEngine.declare(x.optJSONObject("scope"));return wrap(k,name,rr.optBoolean("accepted",false),rr);}
  if("statblock".equals(k)){JSONObject raw=x.optJSONObject("statblock");if(raw==null)raw=x.optJSONObject("record");if(raw==null)return block(k,name,"blocked_missing_statblock");try{JSONObject rec=CompiledStatblockEngine.registerAuthorized(raw);return wrap(k,rec.optString("id"),true,rec);}catch(Exception bad){return block(k,name,"blocked_statblock_authority");}}
  if(!"spell".equals(k)&&!"item".equals(k)&&!"subclass".equals(k)&&!"feat".equals(k))return block(k,name,"blocked_unsupported_kind");JSONObject mechanics=x.optJSONObject("mechanics"),basis=x.optJSONObject("mechanical_basis");JSONObject rr=CompiledContentMechanicsEngine.register(k,name,mechanics,basis);return wrap(k,name,rr.optBoolean("registered",false),rr);
 }catch(Exception e){return block("","","blocked_ingestion_error");}}
 private static JSONObject wrap(String k,String n,boolean ok,JSONObject detail){/*BR_JSON_WRAP_106*/try{return new JSONObject().put("kind",k).put("name",n==null?"":n).put("installed",ok).put("detail",detail==null?new JSONObject():detail);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 private static JSONObject block(String k,String n,String why){/*BR_JSON_WRAP_106*/try{return new JSONObject().put("kind",k).put("name",n==null?"":n).put("installed",false).put("authority",why);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 private static String norm(String s){String x=s==null?"":s.trim().toLowerCase();return "character_option".equals(x)?"subclass":x;}
}
